-- Replace detached guide index lists with contextual screen links in workflow prose.
with revised(slug,title,body) as (values
('bookings-workflow-overview','Bookings: start here','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Start on the "},{"type":"text","text":"Requests","marks":[{"type":"link","attrs":{"href":"/bookings/requests"}}]},{"type":"text","text":" screen to create and price a request. Open an individual request to review the estimate, adjust its scope, plan dates and record delivery."}]},{"type":"paragraph","content":[{"type":"text","text":"Use the "},{"type":"text","text":"Calendar","marks":[{"type":"link","attrs":{"href":"/bookings/calendar"}}]},{"type":"text","text":" to check capacity, holds and term plans; use "},{"type":"text","text":"Rates","marks":[{"type":"link","attrs":{"href":"/bookings/rates/card"}}]},{"type":"text","text":" to inspect the cost model and adopted rate card. Review "},{"type":"text","text":"Partners","marks":[{"type":"link","attrs":{"href":"/bookings/partners"}}]},{"type":"text","text":" for agreements or reserved blocks."}]},{"type":"paragraph","content":[{"type":"text","text":"After delivery, Finance completes settlement on the request. The "},{"type":"text","text":"Term report","marks":[{"type":"link","attrs":{"href":"/bookings/report"}}]},{"type":"text","text":" compares quoted amounts, modeled costs and settled results."}]}]}'::jsonb),
('traffic-workflow-overview','Traffic: start here','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Begin with "},{"type":"text","text":"Contracts","marks":[{"type":"link","attrs":{"href":"/underwriting/contracts"}}]},{"type":"text","text":" to enter and review a signed order. Open its record to manage the schedule, approved messages and agreement; use the "},{"type":"text","text":"Copy library","marks":[{"type":"link","attrs":{"href":"/underwriting/copy"}}]},{"type":"text","text":" for message and DAD cut preparation."}]},{"type":"paragraph","content":[{"type":"text","text":"Check the "},{"type":"text","text":"Traffic dashboard","marks":[{"type":"link","attrs":{"href":"/underwriting"}}]},{"type":"text","text":" for outstanding scheduling and recording work. Resolve missed credits through "},{"type":"text","text":"Exceptions","marks":[{"type":"link","attrs":{"href":"/underwriting/exceptions"}}]},{"type":"text","text":" before preparing "},{"type":"text","text":"Affidavits","marks":[{"type":"link","attrs":{"href":"/underwriting/affidavits"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"For unattended playback, inspect the "},{"type":"text","text":"DAD log","marks":[{"type":"link","attrs":{"href":"/log/dad-log"}}]},{"type":"text","text":" in On Air; releasing a file is separate from confirming that it aired."}]}]}'::jsonb),
('on-air-workflow-overview','On Air: start here','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open "},{"type":"text","text":"Today","marks":[{"type":"link","attrs":{"href":"/log"}}]},{"type":"text","text":" to prepare or run a broadcast rundown. Build reusable items in the "},{"type":"text","text":"Content library","marks":[{"type":"link","attrs":{"href":"/log/library"}}]},{"type":"text","text":" and confirm program timing from "},{"type":"text","text":"Programs","marks":[{"type":"link","attrs":{"href":"/log/programs"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Operations manages unattended periods in "},{"type":"text","text":"Automation","marks":[{"type":"link","attrs":{"href":"/log/automated-hours"}}]},{"type":"text","text":" and eligibility for credits in "},{"type":"text","text":"Underwriting hours","marks":[{"type":"link","attrs":{"href":"/log/underwriting-hours"}}]},{"type":"text","text":". Check source feeds under "},{"type":"text","text":"Sources","marks":[{"type":"link","attrs":{"href":"/log/sources"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Before unattended playback, review and release the "},{"type":"text","text":"DAD log","marks":[{"type":"link","attrs":{"href":"/log/dad-log"}}]},{"type":"text","text":" after resolving its blockers. Verify the file reaches DAD and is played; these are separate steps."}]}]}'::jsonb),
('sourcework-workflow-overview','Sourcework: start here','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Begin on "},{"type":"text","text":"Projects","marks":[{"type":"link","attrs":{"href":"/sourcework"}}]},{"type":"text","text":" to create or open a reporting workspace. Add recordings or documents to the project, then review transcripts and excerpts against the underlying material before quoting them."}]},{"type":"paragraph","content":[{"type":"text","text":"Use the "},{"type":"text","text":"Source Library","marks":[{"type":"link","attrs":{"href":"/sourcework?tab=sources"}}]},{"type":"text","text":" to find existing recordings and documents across projects. Search results help locate sources; they are not independent verification of factual claims."}]}]}'::jsonb),
('editorial-planning-workflow-overview','Editorial Planning: start here','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the "},{"type":"text","text":"Pitch backlog","marks":[{"type":"link","attrs":{"href":"/editorial"}}]},{"type":"text","text":" to submit or revisit a story idea. A useful pitch identifies the public question, evidence, relevance and reporting path."}]},{"type":"paragraph","content":[{"type":"text","text":"In "},{"type":"text","text":"Planning meetings","marks":[{"type":"link","attrs":{"href":"/editorial/meetings"}}]},{"type":"text","text":", editors assemble a slate, compare scores and record dispositions. Manage pitch forms and scoring criteria in "},{"type":"text","text":"Settings","marks":[{"type":"link","attrs":{"href":"/editorial/settings"}}]},{"type":"text","text":"; the rubric informs judgment rather than replacing it."}]}]}'::jsonb),
('audience-listening-workflow-overview','Audience Listening: start here','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Begin with "},{"type":"text","text":"Queries","marks":[{"type":"link","attrs":{"href":"/audience-listening"}}]},{"type":"text","text":" to draft, review and publish a public question. Open the individual query to review submitted recordings and send promising answers to Sourcework."}]},{"type":"paragraph","content":[{"type":"text","text":"Treat submissions as leads and firsthand accounts, not as a representative poll. Verify claims independently before using them in reporting."}]}]}'::jsonb),
('roadmap-workflow-overview','Roadmap: start here','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the "},{"type":"text","text":"Roadmap board","marks":[{"type":"link","attrs":{"href":"/roadmap"}}]},{"type":"text","text":" to see requests and their current status. Use "},{"type":"text","text":"New request","marks":[{"type":"link","attrs":{"href":"/roadmap/new"}}]},{"type":"text","text":" to describe a concrete problem, who experiences it and the result needed."}]},{"type":"paragraph","content":[{"type":"text","text":"Open a request from the board to contribute evidence, clarify a use case or follow the team''s decision. Submitting a request does not commit the station to a delivery date."}]}]}'::jsonb))
update public.rc_articles a set title=r.title, summary='Workflow orientation with contextual links to portal screens.',body=r.body,version_note='Contextual hyperlinks in instructional prose; removed detached guide links',source='release' from revised r where a.slug=r.slug and a.kind='guide' and a.edited_since_release=false returning a.slug,a.version;
